# swoop 0.10.1. Generated by scripts/tap-formula in beatzball/swoop on every
# release: change it there, not here.
class Swoop < Formula
  desc "Keyboard launcher built the Unix way: fzf finds, extensions print lines"
  homepage "https://github.com/beatzball/swoop"
  license "MIT"

  depends_on "fzf"

  on_macos do
    on_arm do
      url "https://github.com/beatzball/swoop/releases/download/v0.10.1/swoop-0.10.1-darwin-arm64.tar.gz"
      sha256 "c8c3dff47bedc1956c806f4c12c784111b2824f514b4fe76f7585df4444bb69a"
    end
    on_intel do
      url "https://github.com/beatzball/swoop/releases/download/v0.10.1/swoop-0.10.1-darwin-amd64.tar.gz"
      sha256 "bddc8bc25d00cb7f591d6a6f2cad01c2e461a839d75b3d69fd831ab92b6cd173"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/beatzball/swoop/releases/download/v0.10.1/swoop-0.10.1-linux-arm64.tar.gz"
      sha256 "23ec069c4c4dd55422b2937b33b39917b6887074834e20f29b11be565a6e9014"
    end
    on_intel do
      url "https://github.com/beatzball/swoop/releases/download/v0.10.1/swoop-0.10.1-linux-amd64.tar.gz"
      sha256 "81691f1359e803e30045394ee5695e3f2a6a7a46fe85bc234b56743f019f673b"
    end
  end

  def install
    # The tarball stays whole under libexec: bin/swoop finds its tools
    # beside itself and the extensions at ../extensions, and the frame
    # needs its resource bundle beside it. Only the commands are linked.
    libexec.install Dir["*"]
    Dir[libexec/"bin/swoop*"].each do |f|
      next if File.basename(f) == "swoop-shell-mac"

      bin.install_symlink f
    end
  end

  # The frame: a panel on alt+shift+space, at login, on a Mac. The
  # clipboard watcher starts itself the first time the launcher runs.
  service do
    run macos: [opt_libexec/"bin/swoop-shell-mac"]
    keep_alive true
    process_type :interactive
    environment_variables PATH: std_service_path_env, SWOOP_LAUNCHER: opt_libexec/"bin/swoop"
    log_path var/"log/swoop.log"
    error_log_path var/"log/swoop.log"
  end

  def caveats
    <<~EOS
      In any terminal, on any OS: swoop

      On a Mac, the frame (a panel on alt+shift+space) runs at login with:
        brew services start swoop
      After that, swoop restart, swoop stop, swoop start, swoop status;
      the bird in the menu bar has Restart and Quit.

      After each upgrade, remove swoop-shell-mac from System Settings,
      Privacy & Security, Accessibility and add it again: releases are
      not signed yet, so a new version needs a new grant.

      The service sees Homebrew's PATH only. If your AI command lives
      elsewhere, name it in full in ~/.config/swoop/ai, for example:
        ~/.local/bin/claude -p
    EOS
  end

  test do
    assert_match "hi", pipe_output("#{bin}/swoop-md -w 40", "# hi\n")
    assert_equal "0.10.1", (libexec/"VERSION").read.strip
  end
end
